verifiche.codice:
extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale deve avviarsi senza errori"):
		return
	check("has_func", has_function(main, "spawn_item_at"), "In basket.gd deve esistere la funzione spawn_item_at")
	check("arg_count", function_argument_count(main, "spawn_item_at") == 2, "spawn_item_at deve accettare due parametri: spawn_pos e item_type")
	var test_pos := Vector2(320.0, 140.0)
	var created = call_if_exists(main, "spawn_item_at", [test_pos, "diamond"])
	if not check("created_item", created is FallingItem, "spawn_item_at deve restituire un'istanza di FallingItem"):
		return
	check("parented", created.get_parent() == main, "L'oggetto creato deve essere aggiunto come figlio con add_child")
	check("pos_ok", created.position == test_pos, "La posizione dell'oggetto deve corrispondere al parametro passato")
	check("type_ok", created.item_name == "diamond", "L'oggetto deve avere il tipo passato tramite apply_item_type")
	var stars_array = get_prop(main, "stars", [])
	check("in_array", created in stars_array, "L'oggetto creato deve essere inserito nell'array stars")
